metadata_sync_diagnostic.source:
#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct MDB_env MDB_env;
/* Confirmed against lmdb.h in both compared LMDB versions. */
#define MDB_NOMETASYNC 0x40000U
int mdb_env_open(MDB_env *env, const char *path, unsigned flags, unsigned mode) {
    int (*open_real)(MDB_env *, const char *, unsigned, unsigned) = dlsym(RTLD_NEXT, "mdb_env_open");
    int (*get_flags)(MDB_env *, unsigned *) = dlsym(RTLD_NEXT, "mdb_env_get_flags");
    if (!open_real || !get_flags) abort();
    const char *strict = getenv("LAB_STRICT_METADATA_SYNC");
    unsigned effective = strict && !strcmp(strict, "1") ? flags & ~MDB_NOMETASYNC : flags;
    int rc = open_real(env, path, effective, mode);
    unsigned actual = 0;
    int flag_rc = rc ? rc : get_flags(env, &actual);
    fprintf(stderr, "LAB_LMDB_FLAGS requested=0x%x effective=0x%x actual=0x%x open_rc=%d flags_rc=%d\n", flags, effective, actual, rc, flag_rc);
    return rc;
}
